import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        // The survivor is always a sum of original values of one index parity.
        long even = 0, odd = 0, largest = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            long v = nextLong();
            largest = Math.max(largest, v);
            if (v > 0) {
                if (i % 2 == 1) odd += v;
                else even += v;
            }
        }
        long best = Math.max(even, odd);
        System.out.println(best > 0 ? best : largest);
    }
}

